CREATE INDEX "findings_recovery_active_idx" ON "finding"."findings" USING btree ("workspace_id","primary_managed_system_id","id") WHERE "finding"."findings"."status" = 'active' AND "finding"."findings"."linked_task_id" IS NULL;--> statement-breakpoint
CREATE INDEX "permission_requests_recovery_open_idx" ON "permission"."permission_requests" USING btree ("workspace_id","id") WHERE "permission"."permission_requests"."status" IN ('pending', 'needs_more_info');--> statement-breakpoint
CREATE INDEX "surveys_recovery_outcome_idx" ON "survey"."surveys" USING btree ("workspace_id","primary_managed_system_id","id") WHERE "survey"."surveys"."type" = 'outcome' AND "survey"."surveys"."status" = 'closed';--> statement-breakpoint
CREATE INDEX "tasks_recovery_released_idx" ON "task"."tasks" USING btree ("workspace_id","primary_managed_system_id","id") WHERE "task"."tasks"."status" = 'released';--> statement-breakpoint
CREATE INDEX "vocs_recovery_unassigned_idx" ON "voc"."vocs" USING btree ("workspace_id","primary_managed_system_id","id") WHERE "voc"."vocs"."archived_at" IS NULL AND "voc"."vocs"."owner_user_id" IS NULL AND "voc"."vocs"."owner_team_id" IS NULL;--> statement-breakpoint
CREATE INDEX "vocs_recovery_high_idx" ON "voc"."vocs" USING btree ("workspace_id","primary_managed_system_id","id") WHERE "voc"."vocs"."archived_at" IS NULL AND "voc"."vocs"."severity" IN ('high', 'critical');